with filtered_store_sales as (select * from store_sales where product_id in (3, 10) and units < 35), product_id_summary as (select product_id, case when revenue >= 3200 then 'high' when revenue >= 800 then 'mid' else 'low' end as revenue_bucket, round(avg(units), 2) as avg_units from filtered_store_sales group by product_id, case when revenue >= 3200 then 'high' when revenue >= 800 then 'mid' else 'low' end) select * from product_id_summary where avg_units >= 35 order by product_id desc, revenue_bucket limit 5;
